// Builder(static ネストクラス)で検索条件を組み立てる
// ここを変えてみよう:minAge を指定しない検索を足す / onlyActive(false) を呼んでみる
class UserQuery {
    private final String dept;
    private final int minAge;
    private final boolean onlyActive;

    // 外から new UserQuery(...) させず、Builder だけが作れるようにする
    private UserQuery(Builder b) {
        this.dept = b.dept;          // Builder の private フィールドも読める
        this.minAge = b.minAge;
        this.onlyActive = b.onlyActive;
    }

    String describe() {
        return "部署=" + dept + " / " + minAge + "歳以上 / "
             + (onlyActive ? "在籍者のみ" : "退職者も含む");
    }

    static class Builder {
        private String dept = "全部署";    // 省略したときの値
        private int minAge = 0;
        private boolean onlyActive = true;

        Builder dept(String dept) { this.dept = dept; return this; }
        Builder minAge(int age) { this.minAge = age; return this; }
        Builder onlyActive(boolean b) { this.onlyActive = b; return this; }

        UserQuery build() { return new UserQuery(this); }
    }
}

// . でつなげて、指定したい項目だけを名前付きで渡す
UserQuery q1 = new UserQuery.Builder().dept("営業").minAge(30).build();
UserQuery q2 = new UserQuery.Builder().build();   // 全部既定値
System.out.println(q1.describe());
System.out.println(q2.describe());

// 内部クラスは外側のインスタンス1つに結び付く
// ここを変えてみよう:car2 の fuel を変える / Gauge に static を付けるとどんなエラーになる?
class Car {
    private final String name;
    private int fuel;
    Car(String name, int fuel) {
        this.name = name;
        this.fuel = fuel;
    }
    void drive(int liters) { fuel -= liters; }

    class Gauge {                       // static なし = 内部クラス
        private final String name = "燃料計";
        String read() {
            // this.name は Gauge 自身、Car.this.name は外側の Car
            return this.name + "(" + Car.this.name + "): 残り " + fuel + "L";
        }
    }

    Gauge gauge() { return new Gauge(); }   // この Car に結び付いた Gauge を作る
}

Car car1 = new Car("社用車A", 40);
Car car2 = new Car("社用車B", 15);
Car.Gauge g1 = car1.gauge();
Car.Gauge g2 = car2.gauge();

car1.drive(12);                 // car1 だけ走らせる
System.out.println(g1.read());  // 外側の最新の fuel を読みに行く
System.out.println(g2.read());

// 匿名クラスの Comparator で並べ方を差し替える
